class SeasonsMenuScreen extends StatefulWidget {
  const SeasonsMenuScreen({super.key});
  @override
  State<SeasonsMenuScreen> createState() => _SeasonsMenuScreenState();
}

class _SeasonsMenuScreenState extends State<SeasonsMenuScreen> {
  late PageController _pageController;
  int _currentPage = 0;
  
  // Economy State
  int _gold = 0;
  int _gems = 0;
  int _lives = 10;
  int _maxLives = 10;
  int _unreadMail = 0;
  int? _targetTime;
  String _timerText = '';
  Timer? _timer;
  List<String> _unlockedSeasons = ['1'];

  @override
  void initState() {
    super.initState();
    _pageController = PageController(viewportFraction: 0.75);
    _loadEconomy();
    _timer = Timer.periodic(const Duration(seconds: 1), (_) => _tick());
  }

  Future<void> _loadEconomy() async {
    final data = await EconomyManager.checkEconomy();
    final prefs = await SharedPreferences.getInstance();
    if (mounted) {
      setState(() {
        _lives = data['lives'];
        _maxLives = data['maxLives'];
        _targetTime = data['targetTime'];
        _gold = data['gold'];
        _gems = data['gems'];
        _unreadMail = data['unreadMail'] ?? 0;
        _unlockedSeasons = prefs.getStringList('ld_unlocked_seasons') ?? ['1'];
      });
    }
  }

  @override
  void _tick() {
    if (_targetTime != null) {
      final diff = DateTime.fromMillisecondsSinceEpoch(_targetTime!).difference(DateTime.now());
      if (diff.isNegative) {
        _loadEconomy();
      } else {
        if(mounted) setState(() { _timerText = '${diff.inMinutes.toString().padLeft(2, '0')}:${(diff.inSeconds % 60).toString().padLeft(2, '0')}'; });
      }
    }
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  // Replaced by GlobalGameHUD

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Stack(
        children: [
          // Background Glow based on current season
          AnimatedContainer(
            duration: const Duration(milliseconds: 500),
            decoration: BoxDecoration(
              gradient: RadialGradient(
                center: const Alignment(0, -0.2),
                radius: 1.5,
                colors: [
                  seasons[_currentPage].color.withOpacity(0.15),
                  const Color(0xFF07080A),
                ],
              ),
            ),
          ),
          
          SafeArea(
            child: SingleChildScrollView(
              child: Column(
                        children: [
                          // ------------------------------------------------ TOP BAR (Economy) ------------------------------------------------
                          GlobalGameHUD(
                            lives: _lives,
                            maxLives: _maxLives,
                            gems: _gems,
                            gold: _gold,
                            unreadMail: _unreadMail,
                            onMailTap: () {
                              showDialog(context: context, builder: (_) => const MailboxDialog()).then((_) => _loadEconomy());
                            },
                            onStoreTap: () {
                              Navigator.push(context, MaterialPageRoute(builder: (_) => const StoreScreen())).then((_) => _loadEconomy());
                            },
                            onSettingsTap: () {
                              showDialog(context: context, builder: (_) => const SettingsDialog()).then((_) => _loadEconomy());
                            },
                          ),
                          
                          const SizedBox(height: 10),
                          const Text('\u{1F608}', style: TextStyle(fontSize: 48)), // Devil emoji
                          const SizedBox(height: 12),
                          Text(
                            'LVL LOOL',
                            style: TextStyle(
                              fontSize: 42,
                              fontWeight: FontWeight.w900,
                              letterSpacing: 8,
                              color: Colors.white,
                              shadows: [
                                const Shadow(color: Colors.redAccent, blurRadius: 20, offset: Offset(0, 0)),
                                const Shadow(color: Colors.red, blurRadius: 5, offset: Offset(2, 2)),
                                Shadow(color: Colors.black.withOpacity(0.8), blurRadius: 0, offset: const Offset(3, 3)),
                              ],
                            ),
                          ),
                          const SizedBox(height: 4),
                          Text(
                            L10n.get('choose_nightmare'),
                            style: TextStyle(
                              fontSize: 12,
                              fontWeight: FontWeight.bold,
                              letterSpacing: 6,
                              color: Colors.white.withOpacity(0.5),
                            ),
                          ),
                          const SizedBox(height: 20),
                          
                          // Carousel
                          SizedBox(
                            height: 450,
                            child: PageView.builder(
                              controller: _pageController,
                              onPageChanged: (idx) => setState(() => _currentPage = idx),
                              itemCount: seasons.length,
                              itemBuilder: (context, index) {
                                final season = seasons[index];
                                return AnimatedBuilder(
                                  animation: _pageController,
                                  builder: (context, child) {
                                    double value = 1.0;
                                    if (_pageController.position.haveDimensions) {
                                      value = _pageController.page! - index;
                                      value = (1 - (value.abs() * 0.25)).clamp(0.0, 1.0);
                                    }
                                    return Center(
                                      child: SizedBox(
                                        height: Curves.easeOut.transform(value) * 450,
                                        width: Curves.easeOut.transform(value) * 350,
                                        child: child,
                                      ),
                                    );
                                  },
                                  child: _buildSeasonCard(season, index),
                                );
                              },
                            ),
                          ),
                          
                          const SizedBox(height: 20),
                          
                          // Page Indicators
                          Row(
                            mainAxisAlignment: MainAxisAlignment.center,
                            children: List.generate(seasons.length, (index) {
                              return GestureDetector(
                                onTap: () {
                                  _pageController.animateToPage(index, duration: const Duration(milliseconds: 400), curve: Curves.easeInOut);
                                },
                                child: AnimatedContainer(
                                  duration: const Duration(milliseconds: 300),
                                  margin: const EdgeInsets.symmetric(horizontal: 4),
                                  width: _currentPage == index ? 32 : 12,
                                  height: 12,
                                  decoration: BoxDecoration(
                                    color: _currentPage == index 
                                        ? seasons[_currentPage].color 
                                        : Colors.white.withOpacity(0.2),
                                    borderRadius: BorderRadius.circular(6),
                                    boxShadow: _currentPage == index ? [BoxShadow(color: seasons[_currentPage].color.withOpacity(0.6), blurRadius: 8, spreadRadius: 2)] : [],
                                  ),
                                ),
                              );
                            }),
                          ),
                          const SizedBox(height: 20),
                        ],
                      ),
                    ),
          ),
        ],
      ),
    );
  }

  Future<void> _handleSeasonTap(SeasonInfo season, int index, int unlockCost) async {
    if (index != _currentPage) {
      _pageController.animateToPage(index, duration: const Duration(milliseconds: 400), curve: Curves.easeInOut);
      return;
    }

    final prefs = await SharedPreferences.getInstance();
    
    // Check if season is locked
    if (!_unlockedSeasons.contains(season.number.toString())) {
      int cost = (season.number - 1) * 1000;
      
      GamePopups.showConfirm(
        context,
        title: 'UNLOCK SEASON?',
        message: 'Do you want to unlock ${season.title} for $cost Gems?',
        color: season.color,
        confirmText: 'UNLOCK',
        onConfirm: () async {
          if (_gems >= cost) {
            // Success
            await prefs.setInt('ld_gems', _gems - cost);
            final newUnlocked = List<String>.from(_unlockedSeasons)..add(season.number.toString());
            await prefs.setStringList('ld_unlocked_seasons', newUnlocked);
            await _loadEconomy();
            if (mounted) {
              GamePopups.showSuccess(
                context,
                title: 'SEASON UNLOCKED!',
                message: 'You have successfully unlocked ${season.title}. Get ready to die.',
              );
            }
          } else {
            // Not enough gems
            if (mounted) {
              GamePopups.showError(
                context,
                message: 'You need $cost Gems to unlock this season!',
                onStoreRoute: () {
                  Navigator.push(context, MaterialPageRoute(builder: (_) => const StoreScreen())).then((_) => _loadEconomy());
                },
              );
            }
          }
        },
      );
      return;
    }

    // Enter Season
    if (mounted) {
      Navigator.push(
        context,
        PageRouteBuilder(
          pageBuilder: (_, __, ___) => SeasonLevelsScreen(season: season),
          transitionsBuilder: (_, anim, __, child) => FadeTransition(opacity: anim, child: child),
        ),
      ).then((_) => _loadEconomy());
    }
  }

  Widget _buildSeasonCard(SeasonInfo season, int index) {
    bool isLocked = !_unlockedSeasons.contains(season.number.toString());
    int unlockCost = (season.number - 1) * 1000;

    return GestureDetector(
      onTap: () => _handleSeasonTap(season, index, unlockCost),
      child: Container(
        margin: const EdgeInsets.symmetric(horizontal: 10, vertical: 20),
        decoration: BoxDecoration(
          color: const Color(0xFF0F111A),
          borderRadius: BorderRadius.circular(32),
          border: Border.all(
            color: isLocked ? Colors.white.withOpacity(0.1) : season.color.withOpacity(0.5),
            width: 2,
          ),
          boxShadow: isLocked ? [] : [
            BoxShadow(color: season.color.withOpacity(0.2), blurRadius: 20, spreadRadius: 2)
          ],
        ),
        child: Stack(
          children: [
            // Internal Glow (only if unlocked)
            if (!isLocked)
              Positioned(
                right: -50, top: -50,
                child: Container(
                  width: 200, height: 200,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    color: season.color.withOpacity(0.15),
                  ),
                ),
              ),
              
            Padding(
              padding: const EdgeInsets.all(32),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    '${L10n.get('season')} ${season.number}',
                    style: TextStyle(
                      color: isLocked ? Colors.white38 : season.color,
                      fontSize: 16,
                      fontWeight: FontWeight.bold,
                      letterSpacing: 2,
                    ),
                  ),
                  const SizedBox(height: 8),
                  Text(season.title,
                    style: TextStyle(
                      color: isLocked ? Colors.white54 : Colors.white,
                      fontSize: 32,
                      fontWeight: FontWeight.w900,
                      height: 1.1,
                    ),
                  ),
                  
                  const SizedBox(height: 20),
                  
                                                                        const Spacer(),
                  
                  // Levels range text
                  Text(
                    '${L10n.get("levels") ?? "LEVELS"} ${season.number == 11 ? 1 : ((season.number - 1) * 20) + 1} - ${season.number == 11 ? 60 : season.number * 20}',
                    style: TextStyle(
                      color: isLocked ? Colors.white24 : Colors.white.withOpacity(0.5),
                      fontSize: 12,
                      fontWeight: FontWeight.bold,
                      letterSpacing: 1,
                    ),
                  ),
                  const SizedBox(height: 16),
                  
                  // 4 Neon Pills
                  if (season.number <= 5)
                    Builder(
                      builder: (context) {
                        const names = [
                          'Appearing Spikes', 'Erratic Spike', 'Jump Drop Floor', 'Darkness',
                          'Time Freeze', 'Inverted Gravity', 'Bouncy', 'Ghost Shadow',
                          'Conveyor Belt', 'Wall Chase', 'Lava Rising', 'Low Gravity',
                          'Flappy Mode', 'Tiny Character', 'Dash', 'Wind',
                          'Ice Floor', 'Screen Blink', 'Mirror Controls', 'Absolute Chaos',
                        ];
                        final m1 = names[season.mechanicOffset];
                        final m2 = names[season.mechanicOffset + 1];
                        final m3 = names[season.mechanicOffset + 2];
                        final m4 = names[season.mechanicOffset + 3];

                        Widget buildPill(String text) {
                          return Expanded(
                            child: Container(
                              padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 4),
                              decoration: BoxDecoration(
                                color: isLocked ? Colors.white.withOpacity(0.02) : season.color.withOpacity(0.05),
                                borderRadius: BorderRadius.circular(10),
                                border: Border.all(
                                  color: isLocked ? Colors.white.withOpacity(0.05) : season.color.withOpacity(0.4),
                                  width: 1.5,
                                ),
                                boxShadow: isLocked ? [] : [
                                  BoxShadow(color: season.color.withOpacity(0.15), blurRadius: 10, spreadRadius: 0)
                                ],
                              ),
                              alignment: Alignment.center,
                              child: Text(
                                text,
                                style: TextStyle(
                                  color: isLocked ? Colors.white30 : season.color.withOpacity(0.9),
                                  fontSize: 10.5,
                                  fontWeight: FontWeight.bold,
                                  letterSpacing: 0.2,
                                ),
                                textAlign: TextAlign.center,
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                              ),
                            ),
                          );
                        }

                        return Column(
                          children: [
                            Row(
                              children: [
                                buildPill(m1),
                                const SizedBox(width: 8),
                                buildPill(m2),
                              ],
                            ),
                            const SizedBox(height: 8),
                            Row(
                              children: [
                                buildPill(m3),
                                const SizedBox(width: 8),
                                buildPill(m4),
                              ],
                            ),
                          ],
                        );
                      }
                    )
                  else if (season.number == 11)
                    Container(
                      padding: const EdgeInsets.symmetric(vertical: 16),
                      decoration: BoxDecoration(
                        color: season.color.withOpacity(0.05),
                        borderRadius: BorderRadius.circular(10),
                        border: Border.all(color: season.color.withOpacity(0.4), width: 1.5),
                        boxShadow: [BoxShadow(color: season.color.withOpacity(0.15), blurRadius: 10, spreadRadius: 0)],
                      ),
                      child: Center(
                        child: Text('ALL 20 MECHANICS', style: TextStyle(color: season.color, fontSize: 12, fontWeight: FontWeight.bold, letterSpacing: 1)),
                      ),
                    ),

                  const SizedBox(height: 20),

                  // Button
                  SizedBox(
                    width: double.infinity,
                    child: ElevatedButton(
                      onPressed: null, // Gesture detector handles it
                      style: ElevatedButton.styleFrom(
                        backgroundColor: isLocked ? Colors.white.withOpacity(0.05) : season.color,
                        disabledBackgroundColor: isLocked ? Colors.white.withOpacity(0.05) : season.color,
                        padding: const EdgeInsets.symmetric(vertical: 16),
                        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
                      ),
                      child: Row(
                        mainAxisAlignment: MainAxisAlignment.center,
                        children: [
                          if (isLocked) ...[
                            const Icon(Icons.lock_outline, color: Colors.white54, size: 18),
                            const SizedBox(width: 8),
                            Text('$unlockCost', style: const TextStyle(color: Colors.white54, fontWeight: FontWeight.w900, fontSize: 16)),
                            const SizedBox(width: 4),
                            const Icon(Icons.diamond_rounded, color: Colors.cyanAccent, size: 18),
                          ] else
                            Text(L10n.get('enter_season') ?? 'ENTER SEASON', style: TextStyle(color: Colors.black, fontWeight: FontWeight.w900, fontSize: 16)),
                        ],
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }

}
class SeasonLevelsScreen extends StatefulWidget {
  final SeasonInfo season;
  const SeasonLevelsScreen({super.key, required this.season});
  @override
  State<SeasonLevelsScreen> createState() => _SeasonLevelsScreenState();
}
class _SeasonLevelsScreenState extends State<SeasonLevelsScreen> {
  
  late List<int> easyRounds;
  late List<int> mediumRounds;
  late List<int> hardRounds;

  int _gold = 0;
  int _gems = 0;
  int _lives = 10;
  int _maxLives = 10;
  int _unreadMail = 0;

  Future<void> _loadEconomy() async {
    final data = await EconomyManager.checkEconomy();
    if (mounted) {
      setState(() {
        _lives = data['lives'];
        _maxLives = data['maxLives'];
        _gold = data['gold'];
        _gems = data['gems'];
        _unreadMail = data['unreadMail'] ?? 0;
      });
    }
  }

  @override
  void initState() {
    super.initState();
    _loadEconomy();
    final mr = widget.season.maxRounds;
    easyRounds = [];
    mediumRounds = [];
    hardRounds = [];

    if (widget.season.levelsPerMechanic == 5) {
      int offset = (widget.season.number - 1) * 20;
      for (int i = 0; i < mr ~/ 5; i++) {
        easyRounds.add(offset + i * 5 + 1);
        easyRounds.add(offset + i * 5 + 2);
        mediumRounds.add(offset + i * 5 + 3);
        mediumRounds.add(offset + i * 5 + 4);
        hardRounds.add(offset + i * 5 + 5);
      }
    } else {
      final cnt = mr ~/ 3;
      easyRounds   = List.generate(cnt, (i) => i * 3 + 1);
      mediumRounds = List.generate(cnt, (i) => i * 3 + 2);
      hardRounds   = List.generate(cnt, (i) => i * 3 + 3);
    }
  }

  // --- Dynamic Helpers ---
  String getLevelName(int round) {
    // Season 6 (The Ultimate Gauntlet): rounds 1..75, no numbers shown
    if (widget.season.number == 6) {
      int rem = (round - 1) % 3;
      if (rem == 0) return 'LVLX';
      if (rem == 1) return 'LVLXX';
      return 'LVLXXX';
    }
    if (widget.season.levelsPerMechanic == 5) {
      int rem = round % 5;
      if (rem == 1) return 'LVL ' + round.toString();
      if (rem == 2) return 'LVLX ' + round.toString();
      if (rem == 3) return 'LVL ' + round.toString();
      if (rem == 4) return 'LVLX ' + round.toString();
      if (rem == 0) return 'LVL ' + round.toString();
    } else {
      int group = (round - 1) ~/ 3 + 1;
      int rem = (round - 1) % 3;
      if (rem == 0) return 'LVL ' + group.toString();
      if (rem == 1) return '+LVL ' + group.toString();
      if (rem == 2) return '++LVL ' + group.toString();
    }
    return 'LVL ' + round.toString();
  }

  String getMechanicName(int globalRound) {
    int localRound = ((globalRound - 1) % widget.season.maxRounds) + 1;
    const names = [
      'Appearing Spikes', 'Erratic Spike', 'Jump Drop Floor', 'Darkness',
      'Time Freeze', 'Inverted Gravity', 'Bouncy', 'Ghost Shadow',
      'Conveyor Belt', 'Wall Chase', 'Lava Rising', 'Low Gravity',
      'Flappy Mode', 'Tiny Character', 'Dash', 'Wind',
      'Ice Floor', 'Screen Blink', 'Mirror Controls', 'Absolute Chaos',
    ];
    int group = ((localRound - 1) ~/ widget.season.levelsPerMechanic) + widget.season.mechanicOffset;
    return group < names.length ? names[group] : '???';
  }

  Color getMechanicColor(int globalRound) {
    int localRound = ((globalRound - 1) % widget.season.maxRounds) + 1;
    const baseColors = [
      Colors.redAccent, Color(0xFFFF6B35), Color(0xFF9B59B6), Color(0xFF3498DB),
      Color(0xFF00BCD4), Color(0xFFFFD700), Color(0xFF1ABC9C), Color(0xFFFF0066),
      Color(0xFFFF9500), Color(0xFF9C27B0), Color(0xFFFF3300), Color(0xFFCCCCCC),
      Color(0xFF00FFFF), Color(0xFF00FF00), Color(0xFFFF00FF), Color(0xFF88FFAA),
      Color(0xFF88CCFF), Color(0xFF4444FF), Color(0xFFFFFFFF), Color(0xFFFF0000),
    ];
    int group = ((localRound - 1) ~/ widget.season.levelsPerMechanic) + widget.season.mechanicOffset;
    Color base = group < baseColors.length ? baseColors[group] : Colors.white;
    // Blend the mechanic base color slightly with the season's main color for thematic unity
    return Color.lerp(base, widget.season.color, 0.3) ?? base;
  }

        void _openLevel(int round) async {
    final data = await EconomyManager.checkEconomy();
    if (data['lives'] <= 0) {
      if (mounted) {
        final result = await showDialog(
          context: context,
          barrierColor: Colors.black.withOpacity(0.85),
          builder: (_) => OutOfLivesDialog(targetTime: data['targetTime'] ?? 0, seasonColor: widget.season.color)
        );
        if (result == true) {
          _openLevel(round);
        }
      }
      return;
    }
    if(!mounted) return;
    Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => _LevelPlayerScreen(
          round: round,
          season: widget.season,
        ),
      ),
    );
  }

  Widget _levelCard(int round, Color sectionColor) {
    final Color mc = getMechanicColor(round);

    return GestureDetector(
      onTap: () => _openLevel(round),
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 300),
        decoration: BoxDecoration(
          color: const Color(0xFF0F111A),
          borderRadius: BorderRadius.circular(14),
          border: Border.all(color: mc.withOpacity(0.35)),
          boxShadow: [BoxShadow(color: mc.withOpacity(0.08), blurRadius: 12, spreadRadius: 1)],
        ),
        child: Stack(
          children: [
            Padding(
              padding: const EdgeInsets.all(13),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisAlignment: MainAxisAlignment.spaceBetween,
                children: [
                  Row(
                    children: [
                      Container(
                        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                        decoration: BoxDecoration(
                          color: mc.withOpacity(0.15),
                          borderRadius: BorderRadius.circular(6),
                        ),
                        child: Text(
                          getLevelName(round),
                          style: TextStyle(
                            color: mc,
                            fontSize: 11, fontWeight: FontWeight.w900, letterSpacing: 0.5,
                          ),
                        ),
                      ),
                      const SizedBox(height: 20),
                      Icon(Icons.play_circle_outline, color: sectionColor.withOpacity(0.45), size: 15),
                    ],
                  ),
                  Text(
                    getMechanicName(round),
                    style: const TextStyle(
                      color: Colors.white70,
                      fontSize: 11, fontWeight: FontWeight.w600,
                    ),
                    maxLines: 2, overflow: TextOverflow.ellipsis,
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildSection({required String title, required String subtitle, required Color color, required IconData icon, required List<int> rounds}) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Container(
          margin: const EdgeInsets.fromLTRB(24, 32, 24, 0),
          padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 14),
          decoration: BoxDecoration(
            color: color.withOpacity(0.07),
            borderRadius: BorderRadius.circular(16),
            border: Border.all(color: color.withOpacity(0.25)),
          ),
          child: Row(
            children: [
              Container(
                width: 42, height: 42,
                decoration: BoxDecoration(color: color.withOpacity(0.12), shape: BoxShape.circle),
                child: Icon(icon, color: color, size: 20),
              ),
              const SizedBox(width: 16),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(title, style: TextStyle(color: color, fontSize: 18, fontWeight: FontWeight.w900, letterSpacing: 0.5)),
                    Text(subtitle, style: TextStyle(color: color.withOpacity(0.55), fontSize: 12)),
                  ],
                ),
              ),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
                decoration: BoxDecoration(color: color.withOpacity(0.12), borderRadius: BorderRadius.circular(20)),
                child: Text('${rounds.length} ${L10n.get('levels')}', style: TextStyle(color: color, fontSize: 12, fontWeight: FontWeight.bold)),
              ),
            ],
          ),
        ),
        const SizedBox(height: 14),
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 24),
          child: LayoutBuilder(builder: (ctx, box) {
            int cols = box.maxWidth > 1200 ? 5 : box.maxWidth > 900 ? 4 : box.maxWidth > 600 ? 3 : 2;
            return GridView.builder(
              shrinkWrap: true,
              physics: const NeverScrollableScrollPhysics(),
              gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                crossAxisCount: cols, childAspectRatio: 1.55, crossAxisSpacing: 10, mainAxisSpacing: 10,
              ),
              itemCount: rounds.length,
              itemBuilder: (_, i) => _levelCard(rounds[i], color),
            );
          }),
        ),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFF07080A),
      body: SingleChildScrollView(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // Header heavily themed by season color
            Stack(
              children: [
                Container(
                  width: double.infinity,
                  padding: const EdgeInsets.fromLTRB(24, 70, 24, 30),
                  decoration: BoxDecoration(
                    color: const Color(0xFF0F111A),
                    border: Border(bottom: BorderSide(color: widget.season.color.withOpacity(0.3), width: 2)),
                    boxShadow: [BoxShadow(color: widget.season.color.withOpacity(0.1), blurRadius: 30)],
                  ),
                  child: Row(
                    children: [
                      Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text('${L10n.get('season')} ${widget.season.number}', style: TextStyle(color: widget.season.color, fontSize: 14, fontWeight: FontWeight.bold, letterSpacing: 2)),
                          const SizedBox(height: 4),
                          Text(widget.season.title, style: const TextStyle(color: Colors.white, fontSize: 32, fontWeight: FontWeight.w900, letterSpacing: 1)),
                          const SizedBox(height: 8),
                          Text('${L10n.get('levels')} ${easyRounds.first} - ${hardRounds.last}', style: TextStyle(color: Colors.white.withOpacity(0.4), fontSize: 13)),
                        ],
                      ),
                    ],
                  ),
                ),
                Positioned(
                  top: 0, left: 0, right: 0,
                  child: SafeArea(
                    child: GlobalGameHUD(
                      lives: _lives,
                      maxLives: _maxLives,
                      gems: _gems,
                      gold: _gold,
                      unreadMail: _unreadMail,
                      onBackTap: () => Navigator.pop(context),
                      onMailTap: () {
                        showDialog(context: context, builder: (_) => const MailboxDialog()).then((_) => _loadEconomy());
                      },
                      onStoreTap: () {
                        Navigator.push(context, MaterialPageRoute(builder: (_) => const StoreScreen())).then((_) => _loadEconomy());
                      },

                      onSettingsTap: () {
                        showDialog(context: context, builder: (_) => const SettingsDialog()).then((_) => _loadEconomy());
                      },
                    ),
                  ),
                ),
              ],
            ),

            _buildSection(
              title: L10n.get('lvl_easy'), subtitle: L10n.get('desc_easy'),
              color: const Color(0xFF00E676), icon: Icons.sentiment_satisfied_alt, rounds: easyRounds,
            ),
            _buildSection(
              title: L10n.get('lvl_medium'), subtitle: L10n.get('desc_medium'),
              color: const Color(0xFFFF9100), icon: Icons.sentiment_neutral, rounds: mediumRounds,
            ),
            _buildSection(
              title: L10n.get('lvl_hard'), subtitle: L10n.get('desc_hard'),
              color: const Color(0xFFFF1744), icon: Icons.sentiment_very_dissatisfied, rounds: hardRounds,
            ),
            const SizedBox(height: 60),
          ],
        ),
      ),
    );
