class _LevelPlayerScreen extends StatefulWidget {
  final int round;
  final SeasonInfo season;

  const _LevelPlayerScreen({required this.round, required this.season});

  @override
  State<_LevelPlayerScreen> createState() => _LevelPlayerScreenState();
}

class _LevelPlayerScreenState extends State<_LevelPlayerScreen> {
  bool _showWinDialog = false;
  bool _showFailDialog = false;
  int _lives = 10;
  int _maxLives = 10;
  int? _targetTime;
  String _timerText = '';
  Timer? _timer;

  @override
  void initState() {
    super.initState();
    _loadEconomy();
    _timer = Timer.periodic(const Duration(seconds: 1), (_) => _tick());
  }

  void _tick() {
    if (_targetTime != null) {
      final diff = DateTime.fromMillisecondsSinceEpoch(_targetTime!).difference(DateTime.now());
      if (diff.isNegative) {
        _loadEconomy();
      } else {
        if(mounted) setState(() { _timerText = '${diff.inMinutes.toString().padLeft(2, '0')}:${(diff.inSeconds % 60).toString().padLeft(2, '0')}'; });
      }
    }
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  int _gold = 0;
  int _gems = 0;
  int _unreadMail = 0;

  Future<void> _loadEconomy() async {
    final data = await EconomyManager.checkEconomy();
    if (mounted) {
      setState(() {
        _lives = data['lives'];
        _maxLives = data['maxLives'];
        _targetTime = data['targetTime'];
        _gold = data['gold'];
        _gems = data['gems'];
        _unreadMail = data['unreadMail'] ?? 0;
      });
    }
  }

  bool _isDialogShowing = false;
  int _earnedGems = 0;
  int _earnedGold = 0;

  void _handleWin(int score) async {
    if (_isDialogShowing) return;
    _isDialogShowing = true;
    final reward = await EconomyManager.processWin(widget.round);
    if (mounted) {
      setState(() {
        _earnedGems = reward['gems'] as int;
        _earnedGold = reward['gold'] as int;
      });
    int rem = widget.round % 5;
    String levelName = 'LVL ';
    if (rem == 1) levelName = 'LVL ';
    else if (rem == 2) levelName = 'LVLX ';
    else if (rem == 3) levelName = 'LVL ';
    else if (rem == 4) levelName = 'LVLX ';
    else if (rem == 0) levelName = 'LVL ';
      
      showDialog(
        context: context,
        barrierDismissible: false,
        barrierColor: Colors.black.withOpacity(0.88),
        builder: (_) => LevelWinDialog(
          round: widget.round,
          season: widget.season,
          earnedGems: _earnedGems,
          earnedGold: _earnedGold,
          levelName: levelName,
          hasNext: widget.round < 660,
        ),
      ).then((_) {
        if (mounted) _isDialogShowing = false;
      });
    }
  }

  void _handleFail() async {
    if (_isDialogShowing) return;
    _isDialogShowing = true;
    await EconomyManager.deductLife();
    await _loadEconomy();
    if (mounted) {
      showDialog(
        context: context,
        barrierDismissible: false,
        barrierColor: Colors.black.withOpacity(0.92),
        builder: (_) => LevelFailDialog(
          round: widget.round,
          season: widget.season,
          onReloadEconomy: _loadEconomy,
        ),
      ).then((_) {
        if (mounted) _isDialogShowing = false;
      });
    }
  }

