  Widget build(BuildContext context) {
    String levelName = "LVL ${widget.round}";
    if (widget.season.number == 6) {
      // Season 6: LVLX / LVLXX / LVLXXX only — no numbers ever
      int rem = (widget.round - 1) % 3;
      if (rem == 0) levelName = 'LVLX';
      else if (rem == 1) levelName = 'LVLXX';
      else levelName = 'LVLXXX';
    } else if (widget.season.levelsPerMechanic == 5) {
      int rem = widget.round % 5;
      if (rem == 1) levelName = "LVL ${widget.round}"; else if (rem == 2) levelName = "LVLX ${widget.round}";
      else if (rem == 3) levelName = "LVL ${widget.round}"; else if (rem == 4) levelName = "LVLX ${widget.round}"; else if (rem == 0) levelName = "LVL ${widget.round}";
    } else {
      int group = (widget.round - 1) ~/ 3 + 1;
      int rem = (widget.round - 1) % 3;
      if (rem == 0) levelName = "LVL $group";
      else if (rem == 1) levelName = "+LVL $group";
      else if (rem == 2) levelName = "++LVL $group";
    }
    
    // Calculate local round (1..20 for normal seasons, 1..60 for retro)
    int localEngineRound = ((widget.round - 1) % widget.season.maxRounds) + 1;

    final hasNext = widget.round < widget.season.maxRounds;

    if (false) { // placeholder Ã¢â‚¬â€ no "under construction" for new seasons

      return Scaffold(
        backgroundColor: const Color(0xFF07080A),
        body: Center(
        child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(Icons.construction, size: 64, color: widget.season.color),
              const SizedBox(height: 16),
              Text('LEVEL ${widget.round} UNDER CONSTRUCTION', style: TextStyle(color: widget.season.color, fontSize: 24, fontWeight: FontWeight.bold)),
              const SizedBox(height: 16),
              ElevatedButton(
                onPressed: () => Navigator.pop(context),
                child: const Text('BACK'),
              ),
            ],
          ),
        ),
      );
    }

    return Scaffold(
      backgroundColor: const Color(0xFF07080A),
      body: Stack(
        children: [
          TrollGame(
            startRound: localEngineRound,
            maxRounds: 1,
            levelsPerMechanic: widget.season.levelsPerMechanic,
            mechanicOffset: widget.season.mechanicOffset,
            onWin: _handleWin,
            onFail: _handleFail,
          ),
          
          Positioned(
            top: 10, left: 0, right: 0,
            child: SafeArea(
              child: Center(
                child: ConstrainedBox(
                  constraints: const BoxConstraints(maxWidth: 800),
                  child: GlobalGameHUD(
                    title: levelName,
                    lives: _lives,
                    maxLives: _maxLives,
                    gems: _gems,
                    gold: _gold,
                    unreadMail: _unreadMail,
                    onBackTap: () => Navigator.pop(context),
                    onMailTap: () {
                      showDialog(context: context, builder: (_) => const MailboxDialog()).then((_) => _loadEconomy());
                    },
                    onStoreTap: () {
                      Navigator.push(context, MaterialPageRoute(builder: (_) => const StoreScreen())).then((_) => _loadEconomy());
                    },

                    onSettingsTap: () {
                      showDialog(context: context, builder: (_) => const SettingsDialog()).then((_) => _loadEconomy());
                    },
                  ),
                ),
              ),
            ),
          ),
          
        ],
      ),
    );
  }
}

