class SettingsDialog extends StatefulWidget {
  const SettingsDialog({super.key});
  @override
  State<SettingsDialog> createState() => _SettingsDialogState();
}

class _SettingsDialogState extends State<SettingsDialog> {
  bool _soundOn = true;
  bool _musicOn = true;
  String _lang = 'en';

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final prefs = await SharedPreferences.getInstance();
    setState(() {
      _soundOn = prefs.getBool('ld_sound') ?? true;
      _musicOn = prefs.getBool('ld_music') ?? true;
      _lang = prefs.getString('ld_lang') ?? 'en';
    });
  }

  Future<void> _toggle(String key, bool val) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setBool(key, val);
  }

  Future<void> _changeLang(String lang) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString('ld_lang', lang);
    setState(() => _lang = lang); globalLanguageNotifier.value = lang; globalLanguageNotifier.value = lang; globalLanguageNotifier.value = lang;
  }

  @override
  Widget build(BuildContext context) {
    return Dialog(
      backgroundColor: Colors.transparent,
      insetPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 24),
      child: Container(
        constraints: const BoxConstraints(maxWidth: 320),
        padding: const EdgeInsets.all(24),
        decoration: BoxDecoration(
          color: const Color(0xFF0F111A), borderRadius: BorderRadius.circular(24),
          border: Border.all(color: Colors.white24),
        ),
        child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
            const Icon(Icons.settings_rounded, color: Colors.white, size: 48),
            const SizedBox(height: 16),
            Text(L10n.get('settings'), style: const TextStyle(color: Colors.white, fontSize: 24, fontWeight: FontWeight.bold, letterSpacing: 2)),
            const SizedBox(height: 24),
            SwitchListTile(
              title: Text(L10n.get('sound_effects'), style: const TextStyle(color: Colors.white)),
              value: _soundOn,
              activeColor: Colors.redAccent,
              onChanged: (v) { setState(() => _soundOn = v); _toggle('ld_sound', v); }
            ),
            SwitchListTile(
              title: Text(L10n.get('music'), style: const TextStyle(color: Colors.white)),
              value: _musicOn,
              activeColor: Colors.redAccent,
              onChanged: (v) { setState(() => _musicOn = v); _toggle('ld_music', v); }
            ),
            const Divider(color: Colors.white24, height: 32),
            const Text('Language / اللغة', style: TextStyle(color: Colors.white70, fontSize: 14)),
            const SizedBox(height: 12),
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: [
                ElevatedButton(
                  style: ElevatedButton.styleFrom(backgroundColor: _lang == 'en' ? Colors.redAccent : Colors.white12, foregroundColor: _lang == 'en' ? Colors.black : Colors.white),
                  onPressed: () => _changeLang('en'),
                  child: const Text('English'),
                ),
                ElevatedButton(
                  style: ElevatedButton.styleFrom(backgroundColor: _lang == 'ar' ? Colors.redAccent : Colors.white12, foregroundColor: _lang == 'ar' ? Colors.black : Colors.white),
                  onPressed: () => _changeLang('ar'),
                  child: const Text('العربية'),
                ),
              ],
            ),
            const SizedBox(height: 24),
            SizedBox(
              width: double.infinity,
              child: ElevatedButton(
                style: ElevatedButton.styleFrom(backgroundColor: Colors.white12, foregroundColor: Colors.white, shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12))),
                onPressed: () => Navigator.pop(context),
                child: Text(L10n.get('close')),
              ),
            ),
          ],
        ),
      ),
    );
  }
}



































class OutOfLivesDialog extends StatefulWidget {
  final int targetTime;
  final Color seasonColor;
  const OutOfLivesDialog({Key? key, required this.targetTime, required this.seasonColor}) : super(key: key);
  @override
  State<OutOfLivesDialog> createState() => _OutOfLivesDialogState();
}

class _OutOfLivesDialogState extends State<OutOfLivesDialog> {
  late Timer _timer;
  int _remaining = 0;

  @override
  void initState() {
    super.initState();
    _remaining = (widget.targetTime - DateTime.now().millisecondsSinceEpoch) ~/ 1000;
    if (_remaining < 0) _remaining = 0;
    _timer = Timer.periodic(const Duration(seconds: 1), (t) {
      if (!mounted) return;
      setState(() {
        _remaining = (widget.targetTime - DateTime.now().millisecondsSinceEpoch) ~/ 1000;
        if (_remaining <= 0) {
          _remaining = 0;
          t.cancel();
          Navigator.pop(context, true);
        }
      });
    });
  }
  @override
  void dispose() { _timer.cancel(); super.dispose(); }

  @override
  Widget build(BuildContext context) {
    int m = _remaining ~/ 60;
    int s = _remaining % 60;
    return Dialog(
      backgroundColor: Colors.transparent,
      child: Container(
        padding: const EdgeInsets.all(24),
        decoration: BoxDecoration(color: const Color(0xFF0F111A), borderRadius: BorderRadius.circular(24), border: Border.all(color: widget.seasonColor.withOpacity(0.5))),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const Icon(Icons.favorite_border, color: Colors.redAccent, size: 48),
            const SizedBox(height: 16),
            Text(L10n.get('out_of_lives') ?? 'OUT OF LIVES', style: TextStyle(color: widget.seasonColor, fontSize: 22, fontWeight: FontWeight.bold)),
            const SizedBox(height: 16),
            Text(L10n.get('refill_in') ?? 'Refill in', style: const TextStyle(color: Colors.white70, fontSize: 16)),
            const SizedBox(height: 8),
            Text(m.toString().padLeft(2, '0') + ':' + s.toString().padLeft(2, '0'), style: const TextStyle(color: Colors.white, fontSize: 32, fontWeight: FontWeight.bold)),
            const SizedBox(height: 24),
            ElevatedButton(
              onPressed: () => Navigator.pop(context),
              style: ElevatedButton.styleFrom(backgroundColor: widget.seasonColor, foregroundColor: Colors.black, shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12))),
              child: const Text('OK', style: TextStyle(fontWeight: FontWeight.bold)),
            ),
          ],
        ),
      ),
    );
  }
}
